CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL,
    name     VARCHAR(500) NOT NULL,
    CONSTRAINT pool_unique UNIQUE (sheet_id, name)
);

-- A pool's members: a person at most once in a pool, with a share percent (more than 0.00, at most 100.00). A person
-- can be in several pools. A retired member's share counts as 0.00 toward the pool's total.
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT        NOT NULL REFERENCES pool (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL,
    CONSTRAINT pool_member_unique UNIQUE (pool_id, person_id)
);
-- A pool's member may be another pool of the sheet instead of a person (exactly one of person_id and member_pool_id
-- is set). A pool is a member of at most one pool, never of itself through any chain, and a chain of pools is at most
-- three deep. A member pool has no pot of its own: its pot is its cut in the pool above.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_pool_unique UNIQUE (member_pool_id);
-- A pool membership may carry a from-date and a to-date (either may be absent: open on that side; to never before
-- from). A member whose dates do not include the sheet's today is left out of the pool entirely: not in its total
-- share, not in its balance, and no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;

